<script setup lang="ts">
import {computed,onMounted,ref,watch,nextTick} from 'vue'
import {useAuthStore} from '@/stores/auth'
import FrequencySourceEditor from '@/components/FrequencySourceEditor.vue'
import {useRoute,useRouter} from 'vue-router'
import {coaching,type Overview} from '@/api/coaching'
import {messageOf} from '@/api/client'
import KnowledgeMindMap from '@/components/KnowledgeMindMap.vue'
import PointStudyPanel from '@/components/PointStudyPanel.vue'
const auth=useAuthStore(),route=useRoute(),router=useRouter(),data=ref<Overview>(),selected=ref(''),query=ref(''),error=ref(''),panel=ref<HTMLElement|null>(null),loading=ref(false)
const point=computed(()=>data.value?.Points.find(p=>p.ID===selected.value))
const subjects=computed(()=>[...new Map((data.value?.Points??[]).map(p=>[p.SubjectID,p.SubjectName])).entries()].sort((a,b)=>['数据结构','计算机组成原理','操作系统','计算机网络'].indexOf(a[1])-['数据结构','计算机组成原理','操作系统','计算机网络'].indexOf(b[1])))
const found=computed(()=>data.value?.Points.filter(p=>p.Name.includes(query.value)||p.Code.toLowerCase().includes(query.value.toLowerCase()))??[])
async function select(id:string){if(!data.value?.Points.some(p=>p.ID===id))return;selected.value=id;await router.replace({query:{...route.query,point:id}});await nextTick();if(window.matchMedia('(max-width:800px)').matches)panel.value?.scrollIntoView({block:'start'})}
async function load(){loading.value=true;error.value='';try{data.value=await coaching.overview();const id=typeof route.query.point==='string'?route.query.point:selected.value;selected.value=data.value.Points.some(p=>p.ID===id)?id:data.value.Points.find(p=>p.Code==='DS.BASIC')?.ID??data.value.Points[0]?.ID??''}catch(e){error.value=messageOf(e)}finally{loading.value=false}}
watch(()=>route.query.point,id=>{if(typeof id==='string'&&data.value?.Points.some(p=>p.ID===id))selected.value=id})
onMounted(load)
</script>
<template><div><header class="page-head"><div><h1>408 知识思维导图</h1><p>先看四科知识结构，再点知识点：读教材 → 听讲解 → 看例题 → 独立练习，用作答结果检查学习漏洞。</p></div></header><p v-if="error" class="notice error" role="alert">{{error}} <button @click="load">重试</button></p><p v-if="loading" role="status">正在读取知识目录与题目覆盖…</p><p class="map-guide">蓝色标记表示参考重要性较高，橙色边框表示有待复查记录；父节点可以汇总下级题组，题组数不代表掌握程度。</p><section class="map-grid"><div class="card map-navigation"><label class="field">定位知识点<input v-model="query" placeholder="名称或知识点编码" aria-label="搜索知识点"/></label><div v-if="query" class="search-results"><p v-if="!found.length">没有找到匹配项，请换一个关键词。</p><button v-for="p in found" :key="p.ID" class="secondary" :class="{selected:p.ID===selected}" @click="select(p.ID)">{{p.Name}}</button></div><div v-else class="map-tree"><details v-for="[id,name] in subjects" :key="id" open><summary>{{name}}</summary><KnowledgeMindMap :points="data?.Points??[]" :subject="id" :selected="selected" @select="select"/></details></div></div><article v-if="point" ref="panel" class="card map-content"><header><h2>{{point.Name}}</h2><p>{{point.Description}}</p><p>{{point.State}} · 本点 {{point.AvailableQuestions}} 个题组，含下级 {{point.SubtreeQuestions??point.AvailableQuestions}} 个</p></header><PointStudyPanel :key="point.ID" :point-id="point.ID" @select="select"/><details class="importance-details"><summary>重要性与考频依据 · {{point.Importance.toFixed(1)}} / 5</summary><p>{{point.ImportanceBasis}}</p><p>库内真题：{{point.ExamYears}} / {{point.CorpusYears}}个本学科已识别年度，不是未来考频预测。</p><p v-if="!point.Sources.length">尚未录入经核对的机构报告。</p><article v-for="f in point.Sources" :key="f.ID"><b>{{f.Organization}} · {{f.StartYear}}–{{f.EndYear}}</b><p>{{f.Appearances}} / {{f.Exams}}个年度</p><a :href="f.URL" target="_blank" rel="noopener noreferrer">{{f.Title}}</a><blockquote>{{f.Excerpt}}</blockquote></article><FrequencySourceEditor v-if="auth.user?.role==='admin'" :point-id="point.ID" @saved="load"/></details></article><article v-else-if="!loading" class="card empty">暂无可用目录，请先检查知识目录。</article></section></div></template>
<style scoped>.map-grid{display:grid;grid-template-columns:minmax(260px,340px) minmax(0,1fr);gap:20px;align-items:start}.map-navigation,.map-content{min-width:0;overflow-wrap:anywhere}.map-tree{max-height:72vh;overflow:auto;padding:8px 0}.map-tree>details{margin:16px 0}.map-tree>details>summary{font-weight:600;cursor:pointer}.map-guide{font-size:13px;color:#64748b;margin-bottom:20px}.map-content>header{padding-bottom:12px;border-bottom:1px solid #e2e8f0}.map-grid p{line-height:1.8}.search-results{display:grid;gap:8px;max-height:70vh;overflow:auto}.search-results .selected{border-color:#2563eb;background:#eff6ff}.importance-details{padding:16px 0}.importance-details>summary{cursor:pointer}@media(max-width:800px){.map-grid{grid-template-columns:1fr}.map-tree{max-height:400px}}</style>
